import { env } from "../env";
import { AiUnavailable, type AiProvider, type ChatMessage, type ChatRequest, type ChatResponse } from "./provider";

type WireMessage = Record<string, unknown>;

function toWire(system: string, messages: ChatMessage[]): WireMessage[] {
  const out: WireMessage[] = [{ role: "system", content: system }];
  for (const m of messages) {
    if (m.role === "user") out.push({ role: "user", content: m.content });
    else if (m.role === "assistant") {
      out.push({
        role: "assistant",
        content: m.content || null,
        ...(m.toolCalls?.length
          ? { tool_calls: m.toolCalls.map((t) => ({ id: t.id, type: "function", function: { name: t.name, arguments: JSON.stringify(t.arguments) } })) }
          : {}),
      });
    } else out.push({ role: "tool", tool_call_id: m.toolCallId, content: m.content });
  }
  return out;
}

/**
 * Works with any API that implements OpenAI-style chat completions with tool calling
 * (Gemini's OpenAI endpoint, Mistral, Groq, OpenRouter, OpenAI...). One retry on
 * rate-limit / server errors, a hard timeout, and no key ever leaves the server.
 */
export function openAiCompatible(): AiProvider {
  const url = `${env.aiBaseUrl}/chat/completions`;
  return {
    name: `openai-compatible:${env.aiModel}`,
    async chat(req: ChatRequest): Promise<ChatResponse> {
      const payload = JSON.stringify({
        model: env.aiModel,
        temperature: 0.2,
        messages: toWire(req.system, req.messages),
        tools: req.tools.map((t) => ({ type: "function", function: { name: t.name, description: t.description, parameters: t.parameters } })),
        tool_choice: "auto",
      });
      let lastError = "";
      for (let attempt = 0; attempt < 2; attempt++) {
        try {
          const res = await fetch(url, {
            method: "POST",
            headers: { "content-type": "application/json", authorization: `Bearer ${env.aiApiKey}` },
            body: payload,
            signal: AbortSignal.timeout(env.aiTimeoutMs),
          });
          if (res.status === 429 || res.status >= 500) {
            lastError = `HTTP ${res.status}`;
            await new Promise((r) => setTimeout(r, 800));
            continue;
          }
          if (!res.ok) throw new AiUnavailable(`AI provider returned HTTP ${res.status}`);
          const json = (await res.json()) as {
            choices?: { message?: { content?: string | null; tool_calls?: { id?: string; function?: { name?: string; arguments?: string } }[] } }[];
            usage?: { prompt_tokens?: number; completion_tokens?: number };
          };
          const msg = json.choices?.[0]?.message;
          if (!msg) throw new AiUnavailable("AI provider returned an empty response");
          const toolCalls = (msg.tool_calls ?? []).map((t, i) => {
            let args: Record<string, unknown> = {};
            try { const p = JSON.parse(t.function?.arguments || "{}"); if (p && typeof p === "object" && !Array.isArray(p)) args = p; } catch {}
            return { id: t.id || `call_${Date.now()}_${i}`, name: String(t.function?.name ?? ""), arguments: args };
          });
          return {
            text: typeof msg.content === "string" ? msg.content : "",
            toolCalls,
            usage: { in: json.usage?.prompt_tokens ?? 0, out: json.usage?.completion_tokens ?? 0 },
          };
        } catch (e) {
          if (e instanceof AiUnavailable) throw e;
          lastError = (e as Error).name === "TimeoutError" ? "timeout" : (e as Error).message;
        }
      }
      throw new AiUnavailable(`AI provider unavailable (${lastError})`);
    },
  };
}
